#define ELLIPSIS "\342\200\246"

/* n with the thousands separator of the locale. */
char *format_count(size_t n)
{
	const struct lconv *lc;
	char digits[32], *out;
	size_t len, sep_len, group = 0, i, o = 0;

	lc = localeconv();
	len = (size_t)snprintf(digits, sizeof digits, "%zu", n);
	sep_len = strlen(lc->thousands_sep);
	if (sep_len > 0 && lc->grouping[0] > 0 && lc->grouping[0] != CHAR_MAX)
		group = (size_t)lc->grouping[0];
	out = xmalloc(len * (sep_len + 1) + 1);
	for (i = 0; i < len; i++) {
		if (group > 0 && i > 0 && (len - i) % group == 0) {
			memcpy(out + o, lc->thousands_sep, sep_len);
			o += sep_len;
		}
		out[o++] = digits[i];
	}
	out[o] = '\0';
	return out;
}

static char *message(const char *key, const char *arg)
{
	char *out;
	int n;

	n = snprintf(NULL, 0, msg(key), arg);
	out = xmalloc(n > 0 ? (size_t)n + 1 : 1);
	if (n <= 0 || snprintf(out, (size_t)n + 1, msg(key), arg) != n)
		out[0] = '\0';
	return out;
}

/*
 * A size in decimal units with one decimal digit, as the Finder shows it.
 * printf takes the decimal point from the locale (LC_NUMERIC).
 */
char *format_size(unsigned long long bytes)
{
	static const char *const keys[] = {
		"size.kB", "size.MB", "size.GB", "size.TB", "size.PB"
	};
	char num[64], *count, *out;
	double v;
	size_t k;

	if (bytes < 1000) {
		count = format_count((size_t)bytes);
		out = message("size.B", count);
		free(count);
		return out;
	}
	v = (double)bytes / 1000.0;
	/* 999.96 kB would print as 1000.0 kB, so it moves up a unit. */
	for (k = 0; v >= 999.95 && k + 1 < sizeof keys / sizeof keys[0]; k++)
		v /= 1000.0;
	snprintf(num, sizeof num, "%.1f", v);
	return message(keys[k], num);
}

/* Local date and time in the catalogue's strftime format; 0 is unknown. */
char *format_time(time_t t)
{
	struct tm tm;
	char buf[128];

	if (t == 0 || localtime_r(&t, &tm) == NULL)
		return xstrdup(msg("value.none"));
	if (strftime(buf, sizeof buf, msg("format.datetime"), &tm) == 0)
		return xstrdup(msg("value.none"));
	return xstrdup(buf);
}

/* ISO 8601 in UTC, for --json. */
char *format_iso(time_t t)
{
	struct tm tm;
	char buf[32];

	if (gmtime_r(&t, &tm) == NULL ||
	    strftime(buf, sizeof buf, "%Y-%m-%dT%H:%M:%SZ", &tm) == 0)
		return xstrdup("1970-01-01T00:00:00Z");
	return xstrdup(buf);
}

/* Days since 1970-01-01 of a proleptic Gregorian date (H. Hinnant). */
static long days_from_civil(long y, long m, long d)
{
	long era, yoe, doy, doe;

	y -= m <= 2;
	era = (y >= 0 ? y : y - 399) / 400;
	yoe = y - era * 400;
	doy = (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + d - 1;
	doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
	return era * 146097 + doe - 719468;
}

static int digits(const char *s, int n, long *v)
{
	int i;

	*v = 0;
	for (i = 0; i < n; i++) {
		if (s[i] < '0' || s[i] > '9')
			return -1;
		*v = *v * 10 + (s[i] - '0');
	}
	return 0;
}

/*
 * A timestamp as Claude Code writes it (2026-10-27T20:12:11.000Z), also
 * with an offset instead of Z. POSIX has no timegm, hence the arithmetic.
 */
int parse_iso(const char *s, time_t *t)
{
	long y, mo, d, h, mi, sec, oh, om, off = 0;
	const char *p;

	if (strlen(s) < 19 || digits(s, 4, &y) != 0 || s[4] != '-' ||
	    digits(s + 5, 2, &mo) != 0 || s[7] != '-' ||
	    digits(s + 8, 2, &d) != 0 || (s[10] != 'T' && s[10] != ' ') ||
	    digits(s + 11, 2, &h) != 0 || s[13] != ':' ||
	    digits(s + 14, 2, &mi) != 0 || s[16] != ':' ||
	    digits(s + 17, 2, &sec) != 0)
		return -1;
	if (mo < 1 || mo > 12 || d < 1 || d > 31 || h > 23 || mi > 59 ||
	    sec > 60)
		return -1;
	p = s + 19;
	if (*p == '.')
		for (p++; *p >= '0' && *p <= '9'; p++)
			;
	if (*p == '+' || *p == '-') {
		if (digits(p + 1, 2, &oh) != 0 || p[3] != ':' ||
		    digits(p + 4, 2, &om) != 0 || p[6] != '\0')
			return -1;
		off = (oh * 60 + om) * 60;
		if (*p == '+')
			off = -off;
	} else if (strcmp(p, "Z") != 0) {
		return -1;
	}
	*t = (time_t)(((days_from_civil(y, mo, d) * 24 + h) * 60 + mi) * 60 +
	    sec + off);
	return 0;
}

/* Length of the UTF-8 sequence at s (1–4), or 0 when it is not valid. */
static size_t utf8_len(const unsigned char *s, unsigned long *cp)
{
	size_t n, i;
	unsigned long c, min;

	if (s[0] < 0x80) {
		*cp = s[0];
		return 1;
	}
	if ((s[0] & 0xe0) == 0xc0) {
		n = 2;
		c = s[0] & 0x1f;
		min = 0x80;
	} else if ((s[0] & 0xf0) == 0xe0) {
		n = 3;
		c = s[0] & 0x0f;
		min = 0x800;
	} else if ((s[0] & 0xf8) == 0xf0) {
		n = 4;
		c = s[0] & 0x07;
		min = 0x10000;
	} else {
		return 0;
	}
	for (i = 1; i < n; i++) {
		if ((s[i] & 0xc0) != 0x80)
			return 0;
		c = c << 6 | (s[i] & 0x3f);
	}
	if (c < min || c > 0x10ffff || (c >= 0xd800 && c <= 0xdfff))
		return 0;
	*cp = c;
	return n;
}

/*
 * Text from a session file made safe for a terminal: control characters
 * (C0, DEL, C1) become spaces, so a prompt cannot send escape sequences,
 * and bytes that are not UTF-8 become "?".
 */
char *text_clean(const char *s)
{
	const unsigned char *p = (const unsigned char *)s;
	unsigned long cp;
	char *out;
	size_t n, o = 0;

	out = xmalloc(strlen(s) + 1);
	while (*p != '\0') {
		n = utf8_len(p, &cp);
		if (n == 0) {
			out[o++] = '?';
			p++;
			continue;
		}
		if (cp < 0x20 || (cp >= 0x7f && cp < 0xa0)) {
			out[o++] = ' ';
		} else {
			memcpy(out + o, p, n);
			o += n;
		}
		p += n;
	}
	out[o] = '\0';
	return out;
}

/* Columns of one character at s, and its length in *len. */
size_t text_char_width(const char *s, size_t *len)
{
	mbstate_t st;
	wchar_t wc;
	size_t n;
	int w;

	memset(&st, 0, sizeof st);
	n = mbrtowc(&wc, s, MB_CUR_MAX, &st);
	if (n == (size_t)-1 || n == (size_t)-2 || n == 0) {
		*len = 1;
		return 1;
	}
	*len = n;
	w = wcwidth(wc);
	return w < 0 ? 1 : (size_t)w;
}

/* Terminal columns of s in the current locale. */
size_t text_width(const char *s)
{
	size_t w = 0, len;

	while (*s != '\0') {
		w += text_char_width(s, &len);
		s += len;
	}
	return w;
}

/* s cut to width columns, with an ellipsis when something was cut. */
char *text_fit(const char *s, size_t width)
{
	const char *p;
	size_t used = 0, w, len;
	char *out;

	if (text_width(s) <= width)
		return xstrdup(s);
	if (width == 0)
		return xstrdup("");
	for (p = s; *p != '\0'; p += len) {
		w = text_char_width(p, &len);
		if (used + w > width - 1)
			break;
		used += w;
	}
	out = xmalloc((size_t)(p - s) + sizeof ELLIPSIS);
	memcpy(out, s, (size_t)(p - s));
	memcpy(out + (p - s), ELLIPSIS, sizeof ELLIPSIS);
	return out;
}

static void add_line(char ***lines, size_t *n, size_t *cap, size_t pad,
    const char *s, size_t len)
{
	char *line;

	while (len > 0 && s[len - 1] == ' ')
		len--;
	if (*n == *cap) {
		*cap = *cap * 2 + 16;
		*lines = xrealloc(*lines, *cap * sizeof **lines);
	}
	line = xmalloc(pad + len + 1);
	memset(line, ' ', pad);
	memcpy(line + pad, s, len);
	line[pad + len] = '\0';
	(*lines)[(*n)++] = line;
}

/*
 * The len bytes of text as lines of at most width columns, broken at
 * spaces. A broken line goes on under its own indent, unless that takes
 * more than half the width; a word wider than the line is cut.
 */
char **text_wrap(const char *text, size_t len, size_t width, size_t *count)
{
	const char *end = text + len, *ls, *le, *p, *q, *brk, *cut;
	char **lines = NULL;
	size_t n = 0, cap = 0, indent, hang, pad, used, w, clen = 1;

	if (width == 0)
		width = 1;
	for (ls = text; ls < end; ls = le + 1) {
		le = memchr(ls, '\n', (size_t)(end - ls));
		if (le == NULL)
			le = end;
		for (indent = 0; ls + indent < le && ls[indent] == ' '; indent++)
			;
		hang = indent * 2 <= width ? indent : 0;
		pad = 0;
		p = ls;
		for (;;) {
			used = pad;
			brk = NULL;
			for (q = p; q < le; q += clen) {
				if (*q == ' ' && q > p && q > ls + indent)
					brk = q;
				w = text_char_width(q, &clen);
				if (clen > (size_t)(le - q))
					clen = (size_t)(le - q);
				if (used + w > width)
					break;
				used += w;
			}
			if (q >= le) {
				add_line(&lines, &n, &cap, pad, p, (size_t)(le - p));
				break;
			}
			cut = brk != NULL ? brk : q > p ? q : q + clen;
			add_line(&lines, &n, &cap, pad, p, (size_t)(cut - p));
			for (p = cut; p < le && *p == ' '; p++)
				;
			if (p >= le)
				break;
			pad = hang;
		}
	}
	*count = n;
	return lines;
}

void text_lines_free(char **lines, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++)
		free(lines[i]);
	free(lines);
}

/* The state of a session directory, as every view names it. */
char *format_state(enum dir_state state)
{
	static const char *const keys[] = {
		"state.active", "state.orphan", "state.unavailable",
		"state.unknown"
	};

	return xstrdup(msg(keys[state]));
}

/* The project of a session directory for people, or its name when unknown. */
char *format_project(const struct session_dir_info *d, const char *home)
{
	char *tilde, *clean;

	if (d->project == NULL)
		return text_clean(d->name);
	tilde = path_tilde(d->project, home);
	clean = text_clean(tilde);
	free(tilde);
	return clean;
}

/* The project of a trash entry, else its session directory, else "–". */
char *format_entry_project(const struct trash_entry *e, const char *home)
{
	char *tilde, *clean;

	if (e->project == NULL)
		return e->dir != NULL ? text_clean(e->dir) :
		    xstrdup(msg("value.none"));
	tilde = path_tilde(e->project, home);
	clean = text_clean(tilde);
	free(tilde);
	return clean;
}
